// Real compiled readiness and temperature callbacks, inert devices only. No HC assembly or Host Main.
using System.IO;
using System.Reflection;
using System.Runtime.Loader;
using System.Text.Json;
class OpenDevice { public bool Value=true,Throw;public int Reads,Writes;public double Duty;public virtual bool IsOpen{get{Reads++;if(Throw)throw new InvalidOperationException("live-open-marker-failure");return Value;}}public void SetFanDuty(double duty){Writes++;Duty=duty;} }
sealed class DerivedOpenDevice:OpenDevice { public override bool IsOpen=>!base.IsOpen; }
sealed class ShadowOpenDevice:OpenDevice { public new bool IsOpen=>false; }
sealed class FieldOpenDevice { public bool IsOpen=true; }
sealed class NullableOpenDevice {public bool? Value;public int Reads;public bool? IsOpen{get{Reads++;return Value;}}}
sealed class ObjectOpenDevice {public object? Value=true;public int Reads;public object? IsOpen{get{Reads++;return Value;}}}
sealed class MissingOpenDevice { }
struct StructOpenDevice {public bool Value;public int Reads;public bool IsOpen{get{Reads++;return Value;}}}
sealed class OpenProfile {public float Temperature;public void SetTemperature(float t)=>Temperature=t;public double GetFanSpeed()=>Temperature;}
static class Checks {
 const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
 static Assembly host=null!;static Type backend=null!;static int checks;static readonly List<object> rows=[],observations=[];static readonly List<string> failures=[];
 static void Check(string name,Action action){checks++;try{action();rows.Add(new{name,ok=true});}catch(Exception e){failures.Add(name+": "+e.Message);rows.Add(new{name,ok=false,error=e.ToString()});}}
 static void Require(bool ok,string message){if(!ok)throw new InvalidOperationException(message);}
 static void Set(object o,string n,object? v)=>o.GetType().GetField(n,F)!.SetValue(o,v);
 static object? Field(object o,string n)=>o.GetType().GetField(n,F)?.GetValue(o);
 static object? Call(object o,string n,params object?[] a){try{return o.GetType().GetMethods(F).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(o,a);}catch(TargetInvocationException e)when(e.InnerException is not null){throw e.InnerException;}}
 static int? ReflectionCount()=>backend.GetField("HcOpenMarkerReflectionCallsForSelfTest",F)?.GetValue(null) as int?;
 sealed class Fixture:IDisposable {
  public readonly object Backend,Route;
  public Fixture(object device){var options=host.GetType("YeManFanHost.HostOptions",true)!.GetMethod("Parse",F)!.Invoke(null,[Array.Empty<string>()]);Backend=Activator.CreateInstance(backend,F,null,[options],null)!;Route=backend.GetMethod("ResolveRouteForSelfTest",F)!.Invoke(null,["HandheldCompanion.Devices.GPD.GPDWin5"])!;Install(device);}
  public void Install(object device)=>Call(Backend,"InstallSelfTestRouteSessionForSelfTest",device,Route,true);
  public (bool Ready,string Reason) Ready(){var args=new object?[]{null,true};return ((bool)Call(Backend,"IsHcSessionReadyForControl",args)!, (string)args[0]!);}
  public void Dispose(){Call(Backend,"DetachCpuTemperatureLoop");backend.GetProperty("IsOpen",F)!.SetValue(Backend,false);Set(Backend,"openAttempted",false);Set(Backend,"hcOpenInvocationStarted",false);Set(Backend,"device",null);Set(Backend,"sessionDeviceReference",null);((IDisposable)Backend).Dispose();}
 }
 static void MainChecks(string mode){
 Check("six readiness reads use live values with one optional reflection entry",()=>{var d=new OpenDevice();using var f=new Fixture(d);var before=ReflectionCount();var reads=d.Reads;for(int i=0;i<6;i++){d.Value=i%2==0;var r=f.Ready();Require(r.Ready==d.Value,"IsOpen result was cached");Require(r.Reason==(d.Value?"ready":"hc-device-is-open-false"),"readiness reason drifted");}Require(d.Reads-reads==6,"getter count changed");var count=ReflectionCount()-before;observations.Add(new{scenario="six-live-open-marker-reads",reflectionCalls=count,getterCalls=d.Reads-reads});if(count.HasValue)Require(count==(mode=="legacy"?6:1),"reflection entries expected "+(mode=="legacy"?6:1)+", got "+count);});
 Check("virtual override stays current after fast binding",()=>{var d=new DerivedOpenDevice();using var f=new Fixture(d);Require(!f.Ready().Ready,"override false was ignored");d.Value=false;Require(f.Ready().Ready,"override live true was ignored");Require(d.Reads==2,"override was not invoked twice");});
 Check("nearest shadowing property keeps original member selection",()=>{var d=new ShadowOpenDevice();using var f=new Fixture(d);Require(!f.Ready().Ready&&!f.Ready().Ready,"base property replaced nearer property");Require(d.Reads==0,"unexpected base getter call");});
 Check("same type different instance cannot reuse an earlier device",()=>{var a=new OpenDevice();var b=new OpenDevice{Value=false};using var f=new Fixture(a);Require(f.Ready().Ready,"initial open failed");f.Install(b);Require(!f.Ready().Ready,"old true result leaked to replacement");f.Install(a);Require(f.Ready().Ready&&a.Reads==2&&b.Reads==1,"returning target is not current");});
 Check("bool field retains reflection fallback and live false",()=>{var d=new FieldOpenDevice();using var f=new Fixture(d);Require(f.Ready().Ready,"field true ignored");d.IsOpen=false;Require(!f.Ready().Ready,"field false ignored");d.IsOpen=true;Require(f.Ready().Ready,"field return to true ignored");});
 Check("nullable property retains unknown and false distinction",()=>{var d=new NullableOpenDevice{Value=true};using var f=new Fixture(d);Require(f.Ready().Ready,"nullable true ignored");d.Value=false;Require(!f.Ready().Ready,"nullable false ignored");d.Value=null;Require(f.Ready().Ready&&d.Reads==3,"unknown marker gained a new prohibition");});
 Check("object property retains original non-bool behavior",()=>{var d=new ObjectOpenDevice();using var f=new Fixture(d);Require(f.Ready().Ready,"object bool true ignored");d.Value=false;Require(!f.Ready().Ready,"object bool false ignored");d.Value="unknown";Require(f.Ready().Ready&&d.Reads==3,"non-bool marker was coerced");});
 Check("missing marker retains existing optional observation behavior",()=>{using var f=new Fixture(new MissingOpenDevice());Require(f.Ready().Ready&&f.Ready().Ready,"missing property became a new device gate");});
 Check("boxed struct getter remains on the original live reflection path",()=>{object d=new StructOpenDevice{Value=true};using var f=new Fixture(d);Require(f.Ready().Ready,"struct true ignored");d.GetType().GetField("Value")!.SetValue(d,false);Require(!f.Ready().Ready,"struct false ignored");Require((int)d.GetType().GetField("Reads")!.GetValue(d)! == 2,"boxed receiver state was copied");});
 Check("failure before binding is not cached and later success still reads",()=>{var d=new OpenDevice{Throw=true};using var f=new Fixture(d);for(int i=0;i<2;i++){try{f.Ready();throw new Exception("getter failure lost");}catch(TargetInvocationException e){Require(e.InnerException is InvalidOperationException inner&&inner.Message=="live-open-marker-failure","first failure wrapper changed");}}d.Throw=false;Require(f.Ready().Ready&&d.Reads==3,"read did not recover");});
 Check("bound getter preserves target exception wrapper and recovers",()=>{var d=new OpenDevice();using var f=new Fixture(d);Require(f.Ready().Ready,"initial read failed");d.Throw=true;for(int i=0;i<2;i++){try{f.Ready();throw new Exception("getter failure lost");}catch(TargetInvocationException e){Require(e.InnerException is InvalidOperationException inner&&inner.Message=="live-open-marker-failure","bound failure wrapper changed");}}d.Throw=false;d.Value=false;Require(!f.Ready().Ready&&d.Reads==4,"cached fault hid new false");});
 Check("retired device reference is rejected before consulting bound marker",()=>{var d=new OpenDevice();using var f=new Fixture(d);Require(f.Ready().Ready,"initial read failed");var count=d.Reads;Set(f.Backend,"device",new OpenDevice());Require(f.Ready()==(false,"device-reference-marker-lost"),"lost device marker accepted");Require(d.Reads==count,"old bound getter was used on retirement");});
 Check("closed backend does not consult previously bound HC marker",()=>{var d=new OpenDevice();using var f=new Fixture(d);Require(f.Ready().Ready,"initial read failed");var count=d.Reads;backend.GetProperty("IsOpen",F)!.SetValue(f.Backend,false);Require(f.Ready()==(false,"backend-is-open-false")&&d.Reads==count,"closed session still read HC");});
 Check("detach drops any cached device and getter",()=>{var d=new OpenDevice();using var f=new Fixture(d);Require(f.Ready().Ready,"initial read failed");Call(f.Backend,"DetachCpuTemperatureLoop");Require(Field(f.Backend,"hcOpenMarkerDevice") is null&&Field(f.Backend,"hcOpenMarkerReader") is null,"detached HC receiver retained");Require(f.Ready().Ready,"subsequent original observation was blocked");});
 Check("real changed-temperature callback reads live IsOpen before each duty write",()=>{var d=new OpenDevice();using var f=new Fixture(d);var source=Activator.CreateInstance(host.GetType("YeManFanHost.HWiNFOTemperatureMonitor",true)!,true)!;var profile=new OpenProfile();Set(f.Backend,"cpuTemperatureMonitor",source);Set(f.Backend,"activeFanProfile",profile);var before=ReflectionCount();var reads=d.Reads;for(int i=0;i<6;i++){Set(source,"sampleReadTick",Environment.TickCount64);Call(f.Backend,"OnTemperatureMonitorChanged",source,(float?)(50+i));Require(d.Writes==i+1&&d.Duty==50+i,"actual temperature/device sequence changed");}Require(d.Reads-reads==6,"temperature callback stopped checking live device");var count=ReflectionCount()-before;observations.Add(new{scenario="six-real-temperature-callbacks",reflectionCalls=count,getterCalls=d.Reads-reads,dutyWrites=d.Writes});if(count.HasValue)Require(count==(mode=="legacy"?6:1),"temperature reflection entries expected "+(mode=="legacy"?6:1)+", got "+count);d.Value=false;Set(source,"sampleReadTick",Environment.TickCount64);Call(f.Backend,"OnTemperatureMonitorChanged",source,(float?)60);Require(d.Writes==6,"false after binding reached the writer");((IDisposable)source).Dispose();});
 Check("a replacement session with false marker still blocks the real temperature writer",()=>{var a=new OpenDevice();using var f=new Fixture(a);Require(f.Ready().Ready,"warm read failed");var d=new OpenDevice{Value=false};f.Install(d);var source=Activator.CreateInstance(host.GetType("YeManFanHost.HWiNFOTemperatureMonitor",true)!,true)!;Set(f.Backend,"cpuTemperatureMonitor",source);Set(f.Backend,"activeFanProfile",new OpenProfile());Set(source,"sampleReadTick",Environment.TickCount64);Call(f.Backend,"OnTemperatureMonitorChanged",source,(float?)70);Require(d.Writes==0&&a.Writes==0&&d.Reads==1,"replacement borrowed warmed open state");((IDisposable)source).Dispose();});
 }
 public static int Main(string[] args){try{var dll=Path.GetFullPath(args[0]);var resolver=new AssemblyDependencyResolver(dll);AssemblyLoadContext.Default.Resolving+=(_,n)=>resolver.ResolveAssemblyToPath(n) is {} p?AssemblyLoadContext.Default.LoadFromAssemblyPath(p):null;host=AssemblyLoadContext.Default.LoadFromAssemblyPath(dll);backend=host.GetType("YeManFanHost.RealHcBackend",true)!;host.GetType("YeManFanHost.Program",true)!.GetProperty("IsSelfTestProcess",F)!.SetValue(null,true);Require(ReflectionCount().HasValue==(args.Length>3&&args[3]=="probe"),"reflection witness escaped its explicit scratch scope");MainChecks(args.Length>2?args[2]:"bound");Require(!AppDomain.CurrentDomain.GetAssemblies().Any(a=>a.GetName().Name=="HandheldCompanion"),"HC assembly was loaded");var data=new{ok=failures.Count==0,checks,failures,results=rows,observations,scope="compiled real readiness + temperature callbacks, fake HC device/profile and manual sample delivery; no Host Main, HC assembly, hardware, OS sleep or CPU benchmark"};File.WriteAllText(args[1],JsonSerializer.Serialize(data));Console.WriteLine(JsonSerializer.Serialize(data));return failures.Count==0?0:1;}catch(Exception e){Console.Error.WriteLine(e);return 2;}}
}
